import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class LocalDate_fromCalendarFields_TriageGen2Test {

    @Test
    public void testFromCalendarFields_ValidDate() {
        // Arrange
        Calendar calendar = new GregorianCalendar();
        calendar.set(2023, Calendar.OCTOBER, 25);

        // Act
        LocalDate result = LocalDate.fromCalendarFields(calendar);

        // Assert
        // Note: Joda LocalDate month is 1-based, Calendar month is 0-based.
        // The method adds 1 to the calendar month, so it should match.
        assertEquals(2023, result.getYear());
        assertEquals(10, result.getMonthOfYear());
        assertEquals(25, result.getDayOfMonth());
    }






}

